import { useState, useEffect, useCallback, useMemo } from 'react';
import { FileSpreadsheet, Download, ChevronLeft, ChevronRight, Save, Pencil, Check, X, Table } from 'lucide-react';
import * as XLSX from 'xlsx';
import { WORKERS } from '@/hooks/useStore';

interface TabelEmployee {
  num: number;
  name: string;
  employeeId: string;
  position: string;
  grade: string;
  days: Record<string, string>;
}

interface TabelTemplate {
  orgName: string;
  department: string;
  docNumber: string;
  periodFrom: string;
  periodTo: string;
  employees: TabelEmployee[];
}

interface TimesheetViewProps {
  tabelData: TabelTemplate | null;
  onSaveTabel: (data: TabelTemplate) => void;
  kpiSession: Record<string, string>;
  workers: typeof WORKERS;
  currentMonth: number;
  currentYear: number;
}

const DAY_CODES: Record<string, { label: string; color: string; bg: string }> = {
  'Я': { label: 'Явка', color: '#107C10', bg: '#DFF6DD' },
  'В': { label: 'Выходной', color: '#616161', bg: '#F3F3F3' },
  'ДО': { label: 'За свой счет', color: '#D83B01', bg: '#FDE7E9' },
  'ОТ': { label: 'Отпуск', color: '#0078D4', bg: '#E5F1FB' },
  'Б': { label: 'Больничный', color: '#FFB900', bg: '#FFF4CE' },
  'К': { label: 'Командировка', color: '#8764B8', bg: '#F0E6FF' },
  'У': { label: 'Учеба', color: '#00B294', bg: '#E0F9F3' },
};

function getDaysInMonth(month: number, year: number): number {
  return new Date(year, month + 1, 0).getDate();
}

export const TimesheetView = ({ tabelData, onSaveTabel, kpiSession, workers, currentMonth, currentYear }: TimesheetViewProps) => {
  const [data, setData] = useState<TabelTemplate | null>(tabelData);
  const [editingCell, setEditingCell] = useState<{ empIdx: number; day: number } | null>(null);
  const [editValue, setEditValue] = useState('');
  const [page, setPage] = useState(0);
  const [autoFillKpi, setAutoFillKpi] = useState(true);
  const [showCodes, setShowCodes] = useState(false);

  const daysInMonth = getDaysInMonth(currentMonth, currentYear);
  const daysArray = useMemo(() => Array.from({ length: daysInMonth }, (_, i) => i + 1), [daysInMonth]);
  const DAYS_PER_PAGE = 15;
  const totalPages = Math.ceil(daysInMonth / DAYS_PER_PAGE);

  const visibleDays = useMemo(() => {
    const start = page * DAYS_PER_PAGE;
    const end = Math.min(start + DAYS_PER_PAGE, daysInMonth);
    return daysArray.slice(start, end);
  }, [page, daysArray]);

  // Auto-fill from KPI when data changes
  useEffect(() => {
    if (!data || !autoFillKpi) return;
    
    const newEmployees = data.employees.map(emp => {
      // Find worker ID by name
      const worker = workers.find(w => {
        const empLastName = emp.name.split(' ')[0];
        return w.name.includes(empLastName);
      });
      
      if (!worker) return emp;
      
      const newDays = { ...emp.days };
      
      // Check KPI for each day
      for (let day = 1; day <= daysInMonth; day++) {
        const key = `${worker.id}_${day}`;
        const kpiVal = kpiSession[key];
        
        if (kpiVal && kpiVal.trim() !== '') {
          // KPI has value - mark as "Я" (attendance)
          newDays[String(day)] = 'Я';
        }
      }
      
      return { ...emp, days: newDays };
    });
    
    setData(prev => prev ? { ...prev, employees: newEmployees } : null);
  }, [kpiSession, autoFillKpi]);

  // Initialize data from template
  useEffect(() => {
    if (tabelData && !data) {
      setData(tabelData);
    }
  }, [tabelData]);

  const handleCellClick = (empIdx: number, day: number) => {
    const currentVal = data?.employees[empIdx].days[String(day)] || '';
    setEditingCell({ empIdx, day });
    setEditValue(currentVal);
  };

  const handleCellSave = () => {
    if (!editingCell || !data) return;
    
    const { empIdx, day } = editingCell;
    const newEmployees = [...data.employees];
    newEmployees[empIdx] = {
      ...newEmployees[empIdx],
      days: {
        ...newEmployees[empIdx].days,
        [String(day)]: editValue.toUpperCase(),
      },
    };
    
    const newData = { ...data, employees: newEmployees };
    setData(newData);
    onSaveTabel(newData);
    setEditingCell(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') handleCellSave();
    if (e.key === 'Escape') setEditingCell(null);
  };

  const exportToExcel = () => {
    if (!data) return;
    
    const wb = XLSX.utils.book_new();
    
    // Build sheet data
    const wsData: any[][] = [];
    
    // Title
    wsData.push([data.orgName]);
    wsData.push([data.department]);
    wsData.push(['ТАБЕЛЬ учета рабочего времени']);
    wsData.push(['Период: ' + data.periodFrom + ' - ' + data.periodTo]);
    wsData.push([]);
    
    // Header
    const headerRow1 = ['№', 'ФИО', 'Таб.№', ...visibleDays.map(String), 'Дни', 'Часы'];
    wsData.push(headerRow1);
    
    // Data
    data.employees.forEach(emp => {
      const row = [
        emp.num,
        emp.name,
        emp.employeeId,
        ...visibleDays.map(d => emp.days[String(d)] || ''),
        Object.values(emp.days).filter(v => v === 'Я').length,
        Object.values(emp.days).filter(v => v === 'Я').length * 8,
      ];
      wsData.push(row);
    });
    
    const ws = XLSX.utils.aoa_to_sheet(wsData);
    XLSX.utils.book_append_sheet(wb, ws, 'Табель');
    XLSX.writeFile(wb, `Табель_${currentMonth + 1}_${currentYear}.xlsx`);
  };

  if (!data) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-8" style={{ background: 'var(--bg-primary)' }}>
        <Table size={48} style={{ color: 'var(--text-tertiary)' }} />
        <p className="mt-4 text-[14px] font-medium" style={{ color: 'var(--text-primary)' }}>Загрузка табеля...</p>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col" style={{ background: 'var(--bg-primary)' }}>
      {/* Header */}
      <div className="flex items-center justify-between p-3 md:p-4 border-b flex-shrink-0 flex-wrap gap-2" style={{ borderColor: 'var(--border)' }}>
        <div className="flex items-center gap-2">
          <FileSpreadsheet size={18} style={{ color: '#107C10' }} />
          <div>
            <h1 className="text-[14px] md:text-[16px] font-semibold" style={{ color: 'var(--text-primary)' }}>Табель Т-13</h1>
            <p className="text-[10px]" style={{ color: 'var(--text-tertiary)' }}>{data.department}</p>
          </div>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          {/* KPI auto-fill toggle */}
          <label className="flex items-center gap-1.5 px-2 py-1 rounded text-[11px] cursor-pointer" style={{ background: 'var(--bg-secondary)', color: 'var(--text-secondary)' }}>
            <input
              type="checkbox"
              checked={autoFillKpi}
              onChange={e => setAutoFillKpi(e.target.checked)}
              className="accent-[var(--accent)]"
            />
            Авто-заполнение из KPI
          </label>

          <button
            onClick={() => setShowCodes(v => !v)}
            className="px-2 py-1 rounded text-[11px] font-medium transition-all"
            style={{ background: showCodes ? 'var(--accent)' : 'var(--bg-secondary)', color: showCodes ? '#fff' : 'var(--text-secondary)', border: '1px solid var(--border)' }}
          >
            Коды
          </button>

          <div className="flex items-center gap-1">
            <button onClick={() => setPage(p => Math.max(0, p - 1))} disabled={page === 0} className="w-7 h-7 rounded flex items-center justify-center" style={{ color: page === 0 ? 'var(--text-tertiary)' : 'var(--text-primary)' }}>
              <ChevronLeft size={14} />
            </button>
            <span className="text-[11px] font-mono px-1" style={{ color: 'var(--text-secondary)' }}>
              {page === 0 ? '1-15' : '16-' + daysInMonth}
            </span>
            <button onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))} disabled={page >= totalPages - 1} className="w-7 h-7 rounded flex items-center justify-center" style={{ color: page >= totalPages - 1 ? 'var(--text-tertiary)' : 'var(--text-primary)' }}>
              <ChevronRight size={14} />
            </button>
          </div>

          <button
            onClick={exportToExcel}
            className="flex items-center gap-1.5 px-3 py-2 rounded-lg text-[12px] font-medium transition-all"
            style={{ background: '#107C10', color: '#fff' }}
          >
            <Download size={14} /> Скачать Excel
          </button>
        </div>
      </div>

      {/* Code legend */}
      {showCodes && (
        <div className="flex items-center gap-3 px-3 py-2 border-b flex-wrap flex-shrink-0" style={{ borderColor: 'var(--border)', background: 'var(--bg-secondary)' }}>
          {Object.entries(DAY_CODES).map(([code, info]) => (
            <span key={code} className="flex items-center gap-1 text-[10px]">
              <span className="w-4 h-4 rounded-sm flex items-center justify-center font-bold text-[9px]" style={{ background: info.bg, color: info.color, border: `1px solid ${info.color}` }}>{code}</span>
              <span style={{ color: 'var(--text-secondary)' }}>{info.label}</span>
            </span>
          ))}
        </div>
      )}

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <table className="w-full border-collapse" style={{ fontSize: 11, fontFamily: "'Segoe UI', sans-serif" }}>
          <thead className="sticky top-0 z-10">
            <tr style={{ background: 'var(--input-bg)' }}>
              <th className="text-center px-1 py-1 font-semibold border" style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border)', width: 24, minWidth: 24, fontSize: 9 }}>№</th>
              <th className="text-left px-2 py-1 font-semibold border" style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border)', width: 160, minWidth: 160, fontSize: 9 }}>ФИО</th>
              <th className="text-left px-1 py-1 font-semibold border hidden md:table-cell" style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border)', width: 70, minWidth: 70, fontSize: 9 }}>Таб.№</th>
              {visibleDays.map(d => (
                <th key={d} className="text-center py-1 font-semibold border" style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border)', width: 22, minWidth: 22, fontSize: 8 }}>{d}</th>
              ))}
              <th className="text-center px-1 py-1 font-semibold border" style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border)', width: 28, minWidth: 28, fontSize: 8 }}>Дни</th>
              <th className="text-center px-1 py-1 font-semibold border" style={{ color: 'var(--text-tertiary)', borderColor: 'var(--border)', width: 28, minWidth: 28, fontSize: 8 }}>Часы</th>
            </tr>
          </thead>
          <tbody>
            {data.employees.map((emp, empIdx) => {
              const workedDays = Object.values(emp.days).filter(v => v === 'Я').length;
              const hours = workedDays * 8;
              
              return (
                <tr key={empIdx} className="border-b hover:bg-[var(--surface-hover)] transition-colors" style={{ borderColor: 'var(--border-subtle)' }}>
                  <td className="text-center px-1 py-0.5 border font-mono text-[10px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-tertiary)' }}>{emp.num}</td>
                  <td className="px-2 py-0.5 border" style={{ borderColor: 'var(--border-subtle)' }}>
                    <div>
                      <p className="text-[11px] font-medium truncate" style={{ color: 'var(--text-primary)' }}>{emp.name}</p>
                      <p className="text-[9px] truncate" style={{ color: 'var(--text-tertiary)' }}>{emp.position} {emp.grade}</p>
                    </div>
                  </td>
                  <td className="px-1 py-0.5 border hidden md:table-cell font-mono text-[9px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-secondary)' }}>{emp.employeeId}</td>
                  
                  {visibleDays.map(day => {
                    const val = emp.days[String(day)] || '';
                    const codeInfo = DAY_CODES[val];
                    const isEditing = editingCell?.empIdx === empIdx && editingCell?.day === day;
                    
                    if (isEditing) {
                      return (
                        <td key={day} className="text-center p-0 border" style={{ borderColor: 'var(--accent)', background: 'var(--surface)' }}>
                          <input
                            autoFocus
                            value={editValue}
                            onChange={e => setEditValue(e.target.value)}
                            onBlur={handleCellSave}
                            onKeyDown={handleKeyDown}
                            className="w-full h-full text-center text-[10px] font-bold outline-none"
                            style={{ background: 'transparent', color: 'var(--text-primary)', width: 22 }}
                            maxLength={3}
                          />
                        </td>
                      );
                    }
                    
                    return (
                      <td
                        key={day}
                        onClick={() => handleCellClick(empIdx, day)}
                        className="text-center py-0.5 border cursor-pointer transition-all"
                        style={{
                          borderColor: 'var(--border-subtle)',
                          background: codeInfo ? codeInfo.bg : 'transparent',
                          minWidth: 22,
                          width: 22,
                        }}
                        title={codeInfo ? codeInfo.label : 'Кликните для редактирования'}
                      >
                        <span className="text-[10px] font-bold" style={{ color: codeInfo ? codeInfo.color : 'var(--text-tertiary)' }}>
                          {val}
                        </span>
                      </td>
                    );
                  })}
                  
                  <td className="text-center px-1 py-0.5 border font-semibold text-[10px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-primary)' }}>{workedDays || ''}</td>
                  <td className="text-center px-1 py-0.5 border font-mono text-[10px]" style={{ borderColor: 'var(--border-subtle)', color: 'var(--text-secondary)' }}>{hours || ''}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Footer */}
      <div className="flex items-center justify-between px-3 py-2 border-t flex-shrink-0" style={{ borderColor: 'var(--border)', background: 'var(--bg-secondary)' }}>
        <span className="text-[10px]" style={{ color: 'var(--text-tertiary)' }}>
          {data.employees.length} сотрудников | Авто-заполнение из KPI: {autoFillKpi ? 'ВКЛ' : 'ВЫКЛ'}
        </span>
        <span className="text-[10px]" style={{ color: 'var(--text-tertiary)' }}>
          Кликните на ячейку дня чтобы отредактировать
        </span>
      </div>
    </div>
  );
};
